{
  "title": "The Gilded Cage: Rescue in Ruin",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Crumbling stone gates flanked by faded royal banners, the iron portcullis half-cocked, and a single lantern swinging in the mist.",
      "characters": ["Kael", "Mira", "Torvin"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper warnings.",
      "visual_description": "Cowering huddled figures in threadbare cloaks, eyes wide, pointing toward a distant spire while clutching children close.",
      "characters": ["Townspeople", "Kael"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrols march through the plaza.",
      "visual_description": "A column of faceless soldiers in tarnished plate armor, boots striking cobblestones in unison, halberds gleaming under grey light.",
      "characters": ["Armored Patrol", "Mira", "Torvin"]
    },
    {
      "scene_number": 4,
      "caption": "The party takes shelter in an old tavern.",
      "visual_description": "Dusty barrels, shattered stained glass, and a bar littered with broken tankards, moonlight spilling through a collapsed roof.",
      "characters": ["Kael", "Mira", "Torvin"]
    },
    {
      "scene_number": 5,
      "caption": "Rumors of a dragon reach their ears.",
      "visual_description": "An old woman whispering by a dying fire, her hand on a rusted sword, her shadow flickering like wings on the wall.",
      "characters": ["Townspeople", "Kael", "Mira"]
    },
    {
      "scene_number": 6,
      "caption": "The party approaches the cursed tower.",
      "visual_description": "A twisted black spire rising from the city center, its surface crawling with thorny vines and glowing runes pulsing slowly.",
      "characters": ["Kael", "Mira", "Torvin"]
    },
    {
      "scene_number": 7,
      "caption": "A magic door bars the tower entrance.",
      "visual_description": "The door ripples like oil, shifting patterns of silver and black, a silent eye opening and closing at its center.",
      "characters": ["Mira", "Kael", "Torvin"]
    },
    {
      "scene_number": 8,
      "caption": "Mira deciphers the door's riddle.",
      "visual_description": "Mira tracing her fingers over the runes, her lips moving silently, the door's surface calming to reveal a keyhole.",
      "characters": ["Mira", "Kael", "Torvin"]
    },
    {
      "scene_number": 9,
      "caption": "Inside the tower, illusions tempt them.",
      "visual_description": "A grand hall filled with floating golden coins and shimmering phantoms of lost loved ones, each figure beckoning softly.",
      "characters": ["Kael", "Mira", "Torvin", "Illusion of a child", "Illusion of a king"]
    },
    {
      "scene_number": 10,
      "caption": "The princess is found in a crystal cage.",
      "visual_description": "Elara suspended in a glowing crystal prism, chains of light binding her wrists, her dress tattered but defiant.",
      "characters": ["Elara", "Kael", "Mira", "Torvin"]
    },
    {
      "scene_number": 11,
      "caption": "A guardian activates—a stone golem.",
      "visual_description": "The crystal cracks as a massive golem rises from the floor, its body made of broken statues and crumbling masonry.",
      "characters": ["Stone Golem", "Kael", "Mira", "Torvin", "Elara"]
    },
    {
      "scene_number": 12,
      "caption": "Torvin holds the golem back.",
      "visual_description": "Torvin bracing his shield against the golem's fist, sparks flying, his boots skidding on the stone floor.",
      "characters": ["Torvin", "Stone Golem", "Kael", "Mira", "Elara"]
    },
    {
      "scene_number": 13,
      "caption": "Mira shatters the crystal prison.",
      "visual_description": "Mira pressing her palms against the crystal, a web of light spreading from her hands, the prism exploding into glittering dust.",
      "characters": ["Mira", "Elara", "Kael", "Torvin"]
    },
    {
      "scene_number": 14,
      "caption": "The tower begins to collapse.",
      "visual_description": "Rocks falling from the ceiling, the golem crumbling to rubble, the floor tilting as the tower groans and splits.",
      "characters": ["Kael", "Mira", "Torvin", "Elara"]
    },
    {
      "scene_number": 15,
      "caption": "The party flees through the city streets.",
      "visual_description": "Running figures dodging falling debris and shattered banners, patrols shouting in the distance, flames licking from windows.",
      "characters": ["Kael", "Mira", "Torvin", "Elara", "Armored Patrol"]
    },
    {
      "scene_number": 16,
      "caption": "They reach the escape bridge.",
      "visual_description": "A long stone bridge spanning a churning river, its far end wreathed in mist, the city burning behind them.",
      "characters": ["Kael", "Mira", "Torvin", "Elara"]
    },
    {
      "scene_number": 17,
      "caption": "A dragon descends to block the bridge.",
      "visual_description": "A massive crimson dragon lands on the bridge, its wings folding, smoke curling from its nostrils as it roars silently.",
      "characters": ["Dragon", "Kael", "Mira", "Torvin", "Elara"]
    },
    {
      "scene_number": 18,
      "caption": "The party escapes across the bridge as dawn breaks.",
      "visual_description": "The dragon rising into the sky as the party crosses, the sun cresting the hills, the ruined city silhouetted against gold.",
      "characters": ["Kael", "Mira", "Torvin", "Elara", "Dragon"]
    }
  ]
}

